// shaper_fenics_f34_phase.v -- the F34 shaper with a PHASE per hit (F07).
//
// GENERATED by gerar_fase.py (research vault, phase F07 of the Simulador_Pulsos_FPGA line)
// from shaper_fenics_f34.v. Identical to it except the FIR head: its taps are read, hit by
// hit, from MEM_PH (shaper_fenics_f34_phase.mif, 64 phases, phase k <-> phi = (k-32)*25/64 ns,
// phi > 0 = the hit arrives later), and the head is in transposed form so every hit keeps its
// own phase. The slow sections need no change (a 25 ns shift moves their gains by < 1e-6).
// Phase 32 (phi = 0) gives the output of shaper_fenics_f34 bit for bit. The 15 head products
// go to DSP blocks; the rest keeps multstyle = "logic". Do not edit by hand: rerun the
// generator after regenerating shaper_fenics_f34.v.
//
// ---------------- the base file, as generated, follows ----------------
`timescale 1ns/100ps

// FENICS shaper, F34 design (Simulacao_MinBias/34_iir_40mhz).
//
// GENERATED by gerar_verilog.py from outputs/estrutura_fir_iir.npz.
// Do not edit the coefficients by hand: rerun the generator instead.
//
// Structure: a 13-tap FIR head for the 8 fast poles (tau 20-40 ns, which
// decay within 1-2 samples at 40 MHz) plus 5 IIR sections for the 6 slow
// poles. The FIR head exists because two fast poles carry residues of
// +527.97 and -527.79 that nearly cancel: summing them once at design time,
// in float64, keeps that cancellation out of the runtime datapath.
//
// First-order sections use the LEAKY form  y += k*(G*x - y). In steady state
// k*(G*x - y) = 0, so the DC gain is EXACTLY G no matter how coarsely k is
// quantized; quantizing k only shifts the time constant. That property is
// what lets the tau = 10.1 ms section IMPOSE a total DC gain of exactly
// zero (its G is computed last, after every other coefficient is quantized).
// Without it the simulator would produce a baseline sag that the real system
// does not have (-0.0167 at 5% occupancy).
//
// Second-order sections use the COUPLED (Gold-Rader) form with state (u,v).
// The naive delta form is unusable here: its DC gain depends on d1+d2, which
// is itself a cancellation (+4.75e-5 and -4.75e-5 for the 1.053 ms pair).
//
// ROUNDING: every product shift adds MEIO = 2**(W_COEF-1) and every output
// shift adds half an LSB. A plain arithmetic shift is FLOOR, so a state
// parked just below zero would emit -1 LSB on every sample. Measured in
// steady state the difference is ~1e-10 of peak, so this is fixed-point
// hygiene rather than a fix for a real defect -- but it costs one adder per
// section, so it stays.
//
// All coefficients are 2-term CSD constants, so each constant multiply below
// synthesizes to two shifts and one add: no DSP blocks, no generic
// multipliers. F34 cost estimate: ~92 adders, about 1797 1-bit full adders.
//
// Validated against the F34 target in integer arithmetic, identical to
// plot_float_vs_circuito.py: shape error 0.0258% of peak,
// steady-state DC gain -1.8e-07.
//
// NOTE: the sampling phase is FIXED at 1.4128 ns after the bunch crossing.
// This filter reproduces ONE phase. Arbitrary phases (jitter, TOF) would
// need a polyphase bank: N coefficient sets, same arithmetic.
(* multstyle = "logic" *) module shaper_fenics_f34_phase
#(
	parameter BITS_IN = 34,
	parameter G_OUT_LOG = 10,
	parameter MEM_PH = "shaper_fenics_f34_phase.mif"
)
(
	input  clock, rst,
	input  signed [BITS_IN-1:0] in,
	input  [5:0] phase,
	output signed [BITS_IN+16:0] out
);

localparam integer W_COEF  = 30;   // coefficient fraction bits
localparam integer B_C     = 12;   // FIR tap fraction bits
localparam integer N_DELAY = 3;    // shared delay of the slow sections
// State width is sized PER SECTION: a section holds at most |G|*|x|*2**EX,
// so it needs (BITS_IN-1) + EX + ceil(log2|G|) + 1 bits, plus guard for the
// transient. A single uniform width overflows the tau = 10.1 ms section (the
// largest EX) at small BITS_IN, while wasting bits on the fast ones. In the
// HITS simulator BITS_IN is 13, which is exactly where that bites.
localparam signed [W_COEF:0] MEIO = 1 <<< (W_COEF-1);

// ------------------------------------------- FIR head, POLYPHASE (F07) -----
// 15 taps x 64 phases from MEM_PH (one wide word per phase, tap 0 in the low bits),
// 14 bits each, Q(B_C) like the constant taps they replace. Transposed form: every hit
// multiplies all taps of ITS phase at once, so past hits keep their own phase.
// Same latency as before: fir_acc[n] = sum_j c_j(phase[n-3-j]) * in[n-3-j].
localparam integer NT = 15;
localparam integer WT = 14;
(* romstyle = "M10K" *) reg [NT*WT-1:0] rom_ph [0:63];
initial $readmemb(MEM_PH, rom_ph);
reg [NT*WT-1:0] w_ph = 0;
reg signed [BITS_IN-1:0] e_ph = 0;
always @(posedge clock) w_ph <= rom_ph[phase];
always @(posedge clock or posedge rst)
	if (rst) e_ph <= 0; else e_ph <= in;
localparam signed [BITS_IN+B_C+4:0] FIR_HALF = 1 <<< (B_C-G_OUT_LOG-1);   // rounding of fir_out
(* multstyle = "dsp" *) reg signed [BITS_IN+WT-1:0] q_ph [0:NT-1];
reg signed [BITS_IN+B_C+4:0] a_ph [0:NT-1];
integer i;
always @(posedge clock or posedge rst)
	if (rst) begin
		for (i = 0; i < NT; i = i + 1) begin q_ph[i] <= 0; a_ph[i] <= 0; end
	end else begin
		for (i = 0; i < NT; i = i + 1) q_ph[i] <= e_ph * $signed(w_ph[i*WT +: WT]);
		a_ph[NT-1] <= q_ph[NT-1];
		for (i = 1; i < NT-1; i = i + 1) a_ph[i] <= a_ph[i+1] + q_ph[i];
		a_ph[0] <= a_ph[1] + q_ph[0] + FIR_HALF;
	end
wire signed [BITS_IN+B_C+4:0] fir_acc = a_ph[0];
// FIR taps are Q(B_C); bring them down to the Q(G_OUT_LOG) output scale.
wire signed [BITS_IN+16:0] fir_out = fir_acc >>> (B_C-G_OUT_LOG);   // FIR_HALF is in a_ph

// ------------------------------- shared delay feeding the slow sections ---
// The pulse only starts at sample N_DELAY and the FIR head already carries
// those zeros in its taps. Feeding the slow sections with `in` directly
// advances them by N_DELAY samples: 0.13% error instead of ~1e-4%.
reg signed [BITS_IN-1:0] xd [0:2];
always @(posedge clock or posedge rst) begin
	if (rst) begin
		for (i = 0; i < 3; i = i + 1) xd[i] <= 0;
	end else begin
		xd[0] <= in;
		for (i = 1; i < 3; i = i + 1) xd[i] <= xd[i-1];
	end
end
wire signed [BITS_IN-1:0] xs = xd[2];
// PIPELINE STAGE 0 (2026-10-01): the closing section's G is not a 2-term CSD
// constant (it is computed last, to impose zero DC gain), so its product is
// split in two registered halves; every other section reads xs one sample
// later (xs_r), so all of them stay aligned. TOTAL LATENCY 7 SAMPLES.
reg  signed [BITS_IN-1:0] xs_r = 0;
always @(posedge clock or posedge rst)
	if (rst) xs_r <= 0; else xs_r <= xs;

// ---- leaky section 0: tau=16.6us
//      k = 1.464844e-03 (+2^-9 -2^-11)   G = -0.253906250
localparam integer EX_L0 = 14;
localparam signed [W_COEF+1:0] K_L0 = 1572864;
localparam signed [W_COEF+1:0] G_L0 = -272629760;
localparam integer WS_L0 = BITS_IN + EX_L0 + 4;
localparam integer WP_L0 = WS_L0 + W_COEF + 2;
reg  signed [WS_L0-1:0] acc_L0 = 0;
wire signed [WP_L0-1:0] tgt_L0 = (G_L0 * (xs_r <<< EX_L0) + MEIO) >>> W_COEF;
reg  signed [WP_L0-1:0] tgt_L0_r = 0;   // pipeline stage 1
always @(posedge clock or posedge rst)
	if (rst) tgt_L0_r <= 0; else tgt_L0_r <= tgt_L0;
wire signed [WP_L0-1:0] inc_L0 = (K_L0 * (tgt_L0_r - acc_L0) + MEIO) >>> W_COEF;
always @(posedge clock or posedge rst)
	if (rst) acc_L0 <= 0; else acc_L0 <= acc_L0 + inc_L0;
wire signed [BITS_IN+16:0] out_L0 =
	(acc_L0 + (1 <<< (EX_L0-G_OUT_LOG-1))) >>> (EX_L0-G_OUT_LOG);

// ---- leaky section 1: tau=48.4us
//      k = 5.187988e-04 (+2^-11 +2^-15)   G = -1.992187500
localparam integer EX_L1 = 15;
localparam signed [W_COEF+1:0] K_L1 = 557056;
localparam signed [W_COEF+1:0] G_L1 = -2139095040;
localparam integer WS_L1 = BITS_IN + EX_L1 + 4;
localparam integer WP_L1 = WS_L1 + W_COEF + 2;
reg  signed [WS_L1-1:0] acc_L1 = 0;
wire signed [WP_L1-1:0] tgt_L1 = (G_L1 * (xs_r <<< EX_L1) + MEIO) >>> W_COEF;
reg  signed [WP_L1-1:0] tgt_L1_r = 0;   // pipeline stage 1
always @(posedge clock or posedge rst)
	if (rst) tgt_L1_r <= 0; else tgt_L1_r <= tgt_L1;
wire signed [WP_L1-1:0] inc_L1 = (K_L1 * (tgt_L1_r - acc_L1) + MEIO) >>> W_COEF;
always @(posedge clock or posedge rst)
	if (rst) acc_L1 <= 0; else acc_L1 <= acc_L1 + inc_L1;
wire signed [BITS_IN+16:0] out_L1 =
	(acc_L1 + (1 <<< (EX_L1-G_OUT_LOG-1))) >>> (EX_L1-G_OUT_LOG);

// ---- leaky section 2: tau=10.1ms (fecha)
//      k = 2.384186e-06 (+2^-19 +2^-21)   G = +0.267446307   <-- G IMPOSED: total DC gain = 0
localparam integer EX_L2 = 23;
localparam signed [W_COEF+1:0] K_L2 = 2560;
localparam signed [W_COEF+1:0] G_L2 = 287168285;
localparam integer WS_L2 = BITS_IN + EX_L2 + 4;
localparam integer WP_L2 = WS_L2 + W_COEF + 2;
reg  signed [WS_L2-1:0] acc_L2 = 0;
// G_L2 = GH_L2 + GL_L2, half of its CSD terms each (pipeline stage 0)
localparam signed [W_COEF+1:0] GH_L2 = 287170560;
localparam signed [W_COEF+1:0] GL_L2 = -2275;
wire signed [WP_L2-1:0] ph_L2 = GH_L2 * (xs <<< EX_L2);
wire signed [WP_L2-1:0] pl_L2 = GL_L2 * (xs <<< EX_L2);
reg  signed [WP_L2-1:0] ph_L2_r = 0, pl_L2_r = 0;
always @(posedge clock or posedge rst)
	if (rst) begin ph_L2_r <= 0; pl_L2_r <= 0; end
	else     begin ph_L2_r <= ph_L2; pl_L2_r <= pl_L2; end
wire signed [WP_L2-1:0] tgt_L2 = (ph_L2_r + pl_L2_r + MEIO) >>> W_COEF;
reg  signed [WP_L2-1:0] tgt_L2_r = 0;   // pipeline stage 1
always @(posedge clock or posedge rst)
	if (rst) tgt_L2_r <= 0; else tgt_L2_r <= tgt_L2;
wire signed [WP_L2-1:0] inc_L2 = (K_L2 * (tgt_L2_r - acc_L2) + MEIO) >>> W_COEF;
always @(posedge clock or posedge rst)
	if (rst) acc_L2 <= 0; else acc_L2 <= acc_L2 + inc_L2;
wire signed [BITS_IN+16:0] out_L2 =
	(acc_L2 + (1 <<< (EX_L2-G_OUT_LOG-1))) >>> (EX_L2-G_OUT_LOG);

// ---- coupled (Gold-Rader) section 0: tau=1052.7us (par)
//      c = 1-Re(z) = 2.288818e-05   s = Im(z) = 4.917383e-07
localparam integer EX_A0 = 20;
localparam signed [W_COEF+1:0] C_A0 = 24576;
localparam signed [W_COEF+1:0] S_A0 = 528;
localparam signed [W_COEF+1:0] RA_A0 = 1280;
localparam signed [W_COEF+1:0] RB_A0 = -40;
localparam integer WS_A0 = BITS_IN + EX_A0 + 4;
localparam integer WP_A0 = WS_A0 + W_COEF + 2;
reg  signed [WS_A0-1:0] u_A0 = 0, v_A0 = 0;
wire signed [WP_A0-1:0] xn_A0 = xs_r <<< EX_A0;
wire signed [WP_A0-1:0] fa_A0 = (RA_A0*xn_A0 + MEIO) >>> W_COEF;
wire signed [WP_A0-1:0] fb_A0 = (RB_A0*xn_A0 + MEIO) >>> W_COEF;
reg  signed [WP_A0-1:0] fa_A0_r = 0, fb_A0_r = 0;   // pipeline stage 1
always @(posedge clock or posedge rst)
	if (rst) begin fa_A0_r <= 0; fb_A0_r <= 0; end
	else     begin fa_A0_r <= fa_A0; fb_A0_r <= fb_A0; end
// Feedback sum as a 2-level tree (2026-10-02): (u - C*u) + (fa - S*v).
// Same integer result as the serial chain; shorter loop path.
wire signed [WP_A0-1:0] cu_A0 = (C_A0*u_A0 + MEIO) >>> W_COEF;
wire signed [WP_A0-1:0] cv_A0 = (C_A0*v_A0 + MEIO) >>> W_COEF;
wire signed [WP_A0-1:0] su_A0 = (S_A0*u_A0 + MEIO) >>> W_COEF;
wire signed [WP_A0-1:0] sv_A0 = (S_A0*v_A0 + MEIO) >>> W_COEF;
wire signed [WP_A0-1:0] un_A0 = (u_A0 - cu_A0) + (fa_A0_r - sv_A0);
wire signed [WP_A0-1:0] vn_A0 = (v_A0 - cv_A0) + (fb_A0_r + su_A0);
always @(posedge clock or posedge rst) begin
	if (rst) begin u_A0 <= 0; v_A0 <= 0; end
	else     begin u_A0 <= un_A0; v_A0 <= vn_A0; end
end
wire signed [BITS_IN+16:0] out_A0 =
	((u_A0 <<< 1) + (1 <<< (EX_A0-G_OUT_LOG-1))) >>> (EX_A0-G_OUT_LOG);

// ---- coupled (Gold-Rader) section 1: tau=21.3us (par)
//      c = 1-Re(z) = 1.220703e-03   s = Im(z) = 1.708984e-03
localparam integer EX_A1 = 14;
localparam signed [W_COEF+1:0] C_A1 = 1310720;
localparam signed [W_COEF+1:0] S_A1 = 1835008;
localparam signed [W_COEF+1:0] RA_A1 = 57344;
localparam signed [W_COEF+1:0] RB_A1 = 49152;
localparam integer WS_A1 = BITS_IN + EX_A1 + 4;
localparam integer WP_A1 = WS_A1 + W_COEF + 2;
reg  signed [WS_A1-1:0] u_A1 = 0, v_A1 = 0;
wire signed [WP_A1-1:0] xn_A1 = xs_r <<< EX_A1;
wire signed [WP_A1-1:0] fa_A1 = (RA_A1*xn_A1 + MEIO) >>> W_COEF;
wire signed [WP_A1-1:0] fb_A1 = (RB_A1*xn_A1 + MEIO) >>> W_COEF;
reg  signed [WP_A1-1:0] fa_A1_r = 0, fb_A1_r = 0;   // pipeline stage 1
always @(posedge clock or posedge rst)
	if (rst) begin fa_A1_r <= 0; fb_A1_r <= 0; end
	else     begin fa_A1_r <= fa_A1; fb_A1_r <= fb_A1; end
// Feedback sum as a 2-level tree (2026-10-02): (u - C*u) + (fa - S*v).
// Same integer result as the serial chain; shorter loop path.
wire signed [WP_A1-1:0] cu_A1 = (C_A1*u_A1 + MEIO) >>> W_COEF;
wire signed [WP_A1-1:0] cv_A1 = (C_A1*v_A1 + MEIO) >>> W_COEF;
wire signed [WP_A1-1:0] su_A1 = (S_A1*u_A1 + MEIO) >>> W_COEF;
wire signed [WP_A1-1:0] sv_A1 = (S_A1*v_A1 + MEIO) >>> W_COEF;
wire signed [WP_A1-1:0] un_A1 = (u_A1 - cu_A1) + (fa_A1_r - sv_A1);
wire signed [WP_A1-1:0] vn_A1 = (v_A1 - cv_A1) + (fb_A1_r + su_A1);
always @(posedge clock or posedge rst) begin
	if (rst) begin u_A1 <= 0; v_A1 <= 0; end
	else     begin u_A1 <= un_A1; v_A1 <= vn_A1; end
end
wire signed [BITS_IN+16:0] out_A1 =
	((u_A1 <<< 1) + (1 <<< (EX_A1-G_OUT_LOG-1))) >>> (EX_A1-G_OUT_LOG);

// ------------------------------------------------------------- output ----
// PIPELINE STAGE 2 (01_Timing_40MHz, 2026-07-21): register every component
// output before the final sum. Without this the path 'FIR DSP cascade ->
// output sum -> clip' is combinational end to end and closes at 26.45 MHz
// in the full HITS build (slack -12.8 ns at 40 MHz): the Quartus maps the
// 13-tap FIR sum onto a SERIAL chain of DSP MACs (~21 ns) and the adder
// chain to the clip adds ~16 ns more. Registering the components splits it.
// Every term is delayed by exactly one sample, so the SHAPE IS UNCHANGED:
// out_new[n] = out_old[n-1]: +1 sample (3 -> 4; stage 1 above made it 5).
// Anything aligned downstream shifts with it: golden VCDs, and the anchor
// alignment of the baseline estimator (EST_LATENCIA, EST_IA_INIT).
reg signed [BITS_IN+16:0] fir_out_r, out_L0_r, out_L1_r, out_L2_r, out_A0_r, out_A1_r;
always @(posedge clock or posedge rst) begin
	if (rst) begin
		fir_out_r <= 0;
		out_L0_r <= 0;
		out_L1_r <= 0;
		out_L2_r <= 0;
		out_A0_r <= 0;
		out_A1_r <= 0;
	end else begin
		fir_out_r <= fir_out;
		out_L0_r <= out_L0;
		out_L1_r <= out_L1;
		out_L2_r <= out_L2;
		out_A0_r <= out_A0;
		out_A1_r <= out_A1;
	end
end

// PIPELINE STAGE 3 (2026-10-01): the final sum is registered too, so the
// path 'components -> sum -> noise -> ADC clip' is split. +1 sample:
// Shape unchanged, as for the other stages (total latency: see stage 0).
wire signed [BITS_IN+16:0] soma = fir_out_r
	+ out_L0_r
	+ out_L1_r
	+ out_L2_r
	+ out_A0_r
	+ out_A1_r;
reg  signed [BITS_IN+16:0] out_r = 0;
always @(posedge clock or posedge rst)
	if (rst) out_r <= 0; else out_r <= soma;
assign out = out_r;

endmodule
